        vm.warp(20);
        uint balanceBefore = address(c).balance;
        vm.prank(address(0x02));
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // For the reference: pastBlockTime != 0 after first call, so second call succeeds and sends Ether
        // For the mutant: first call reverts (pastBlockTime==0 fails), so pastBlockTime remains 0, second call also reverts (requires pastBlockTime==0 fails because block.timestamp>0)
        // So the observable divergence: reference's second call succeeds (ok2==true), mutant reverts (ok2==false).
        assertTrue(ok2 == true);
    }
