pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: give an account some ether and warp to a non-zero timestamp
        address alice = address(0x1234);
        vm.deal(alice, 20 ether);
        vm.warp(1000);
        vm.roll(1);

        // First call: succeeds on both contracts and sets pastBlockTime on reference
        vm.prank(alice);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        // Warp forward so timestamp > pastBlockTime (which is 1000 on reference, still 0 on buggy)
        vm.warp(1001);

        // Second call: on reference it succeeds (timestamp 1001 > 1000), on buggy it reverts (1001 > 0 still true? wait, buggy never updates, so pastBlockTime=0, 1001 > 0, so it would succeed. Need timestamp <= pastBlockTime for revert on buggy? Actually buggy never sets pastBlockTime, so it stays 0. After first call on reference, pastBlockTime=1000. For buggy, pastBlockTime=0. Making the second call with timestamp <= 0 is impossible. We need a scenario where reference's pastBlockTime > buggy's pastBlockTime to cause revert on buggy? Let me reconsider.

        // Actually the bug is that pastBlockTime never updates, so after a first call on reference, pastBlockTime = block.timestamp. On buggy, it stays 0. So on a second call with timestamp > 0, buggy would succeed (since 0 < any positive), reference would require timestamp > previous timestamp (1000). So if we call with timestamp 1, reference reverts (1 > 1000 false), buggy succeeds (1 > 0 true). Let me adjust.

        vm.warp(1);

        // Second call: reference reverts (1 <= 1000), buggy succeeds (1 > 0)
        bool ok2;
        if (block.timestamp > c.pastBlockTime()) {
            // On reference, pastBlockTime was set to 1000, so this condition fails
            vm.prank(alice);
            (ok2,) = address(c).call{value: 10 ether}("");
        } else {
            // Actually we should just try and catch
            vm.prank(alice);
            bytes memory payload = "";
            (bool success,) = address(c).call{value: 10 ether}(payload);
            ok2 = success;
        }

        // Assert: the reference does NOT accept the second call (since timestamp not greater than prior), but buggy does
        // We need to check behavior: reference should have pastBlockTime > block.timestamp, so fallback reverts
        // But we already know the outcome: call either reverts or succeeds. We'll use try/catch.
        vm.warp(1);
        vm.prank(alice);
        bool accepted;
        try c.call{value: 10 ether}("") {
            accepted = true;
        } catch {
            accepted = false;
        }
        // On reference, accepted = false (reverts because 1 <= 1000), on buggy, accepted = true (since 1 > 0)
        assertTrue(!accepted, "reference should revert, buggy accepts");
    }
}

