        // First call to set pastBlockTime
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");
        // Now pastBlockTime = 1000, block.number assumed 1 (or any), we warp and roll to make block.number multiple of 15
        vm.warp(2000);
        vm.roll(15); // block.number = 15, so 15 % 15 == 0
        uint256 balanceBefore = address(c).balance;
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        require(ok2, "second call failed");
        uint256 balanceAfter = address(c).balance;
        // In reference (P): balanceAfter = balanceBefore - 10 (since 10 ether transferred out when block.number % 15 == 0)
        // In bug (M): balanceAfter = balanceBefore (since transfer skipped when block.number % 15 != 0)
        assertTrue(balanceAfter == balanceBefore - 10 ether, "balanceAfter should be balanceBefore - 10 ether");
    }
}

