        // In the reference (correct): transfer happens → balance decreases by 10 ether → balanceAfter == balanceBefore - 10 ether
        // In the bug: transfer does NOT happen → balance unchanged → balanceAfter == balanceBefore
        // We assert the reference behavior: balanceAfter == balanceBefore - 10 ether
        // The bug will fail this assertion because balanceAfter == balanceBefore
        assertTrue(balanceAfter == balanceBefore - 10 ether, "Reference should transfer balance when block.number % 15 == 0");
    }
}

